# Generated by axklim/workenv's release workflow from
# packaging/workenv.rb.tmpl. Edit it there — the next release overwrites
# this file.
class Workenv < Formula
  desc "Open a task's git worktree, tmux session and terminal in one command"
  homepage "https://github.com/axklim/workenv"
  # No explicit version, and the asset names below are why it is safe to
  # leave out. Homebrew scans the version from the URL and `brew audit`
  # rejects stating it as well; but an `…-arm64.tar.gz` suffix gave the scan
  # a bare "64" to find, which is how a v0.1.1 formula shipped reporting its
  # version as "64". The platform labels carry no digits, so the version is
  # the only number in the name and the scan cannot pick the wrong one.
  license "MIT"

  depends_on "gh"
  depends_on "tmux"
  uses_from_macos "git"

  on_macos do
    depends_on arch: :arm64

    on_arm do
      url "https://github.com/axklim/workenv/releases/download/v0.3.0/workenv-0.3.0-macos-arm.tar.gz"
      sha256 "b1879a7e163f176c06525f38d08c937660849e1fe5b4ffe42ba7cb4725f7c11c"
    end
  end

  on_linux do
    on_intel do
      url "https://github.com/axklim/workenv/releases/download/v0.3.0/workenv-0.3.0-linux-intel.tar.gz"
      sha256 "e2605414757589e077de9c470368c803bbe20ca1456851e18ab4fd1b6c6437e3"
    end
    on_arm do
      url "https://github.com/axklim/workenv/releases/download/v0.3.0/workenv-0.3.0-linux-arm.tar.gz"
      sha256 "2678940b84a19d5159325c13e20fe7d99d2891310aa417a662ea78f39550bf91"
    end
  end

  def install
    bin.install "we"
    pkgshare.install "skills"
  end

  def caveats
    <<~EOS
      we opens its terminal with Ghostty, which a formula cannot depend on:

        brew install --cask ghostty

      It also runs `claude` in the first tmux window. Claude Code is not a
      Homebrew package — install it separately, or point claude_cmd at
      something else in ~/.config/workenv/config.toml.

      Neither is needed for `we open --no-terminal`, nor on a remote host
      reached with `we --host`.

      The Claude Code skills that drive `we` (/we, /we-remove, /we-list)
      ship here:

        #{pkgshare}/skills

      Link every one into ~/.claude/skills/ (or let your dotfiles do it) so
      the skills always match the installed version:

        for s in #{pkgshare}/skills/*; do ln -s "$s" ~/.claude/skills/; done
    EOS
  end

  test do
    # The check nothing else can make: a formula bumped to a version whose
    # asset was built from something else.
    assert_equal version.to_s, shell_output("#{bin}/we --version").strip

    # `we` with no arguments exits non-zero, so the usage check uses `help`.
    assert_match "we open", shell_output("#{bin}/we help")
    %w[we we-remove we-list].each do |skill|
      assert_path_exists pkgshare/"skills/#{skill}/SKILL.md"
    end
  end
end
